#include "feature_acceleration.hpp"
#include "feature_advanced.hpp"
#include <atomic>
#include <fstream>
#include <iostream>
using namespace scratcher;
namespace {
size_t checks=0;
void check(bool condition,const char* message){++checks;if(!condition)throw std::runtime_error(message);}
Json tool(Engine& e,const char* name,Json args=Json::object()){auto value=callAccelerationTool(e,name,args);if(!value)throw std::runtime_error("Unknown acceleration tool");return *value;}
bool throws(Engine& e,const char* name,Json args=Json::object()){try{tool(e,name,args);return false;}catch(const std::exception&){return true;}}
void fixture(Engine& e,const std::filesystem::path& root){std::vector<uint8_t> bytes(24*32,0xcc);for(size_t n=0;n<24;++n){size_t at=n*32;bytes[at]=0x48;bytes[at+1]=0xb8;uint64_t immediate=n==1?0x180001000:0x140001000;std::memcpy(bytes.data()+at+2,&immediate,8);bytes[at+10]=bytes[at+11]=0x90;bytes[at+12]=0xc3;}std::vector<uint8_t> different={0x31,0xc0,0x29,0xd1,0x0f,0xaf,0xc1,0xff,0xc0,0xc3};std::copy(different.begin(),different.end(),bytes.begin()+23*32);auto file=root/"prefixes.bin";{std::ofstream stream(file,std::ios::binary);stream.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());}e.open(file);auto b=e.editableBinary();b->functions.clear();for(size_t n=0;n<24;++n)b->functions.push_back({0x1000+n*32,0,"fixture_"+std::to_string(n),"test metadata candidate"});}
}
int main(){try{auto root=executableDir()/"acceleration-feature-fixtures";std::filesystem::create_directories(root);Engine e;auto info=tool(e,"get_acceleration_info");check(info.contains("gpu")&&info["index"]["available"]==false,"GPU probe works with no binary/index");check(throws(e,"build_function_similarity_index"),"index requires open binary");fixture(e,root);auto originalFunctions=e.binary()->functions.size();auto first=tool(e,"build_function_similarity_index",{{"workers",1}});check(first["index_size"]==24&&first["processed_functions"]==24,"all valid four-instruction prefixes indexed");check(first["coverage_modified"]==false&&first["semantic_equivalence_proven"]==false,"similarity does not claim analysis coverage or semantics");check(e.binary()->functions.size()==originalFunctions,"similarity preserves candidate function index");auto page=tool(e,"get_function_similarity_index",{{"limit",5000}});check(page["items"][0]["fingerprint_256"].get<std::string>().size()==64,"fingerprint is exactly256bitshex");check(page["items"][0]["fingerprint_256"]==page["items"][1]["fingerprint_256"],"rebased absolute immediate values excluded from fingerprint");check(page["items"][0]["fingerprint_256"]!=page["items"][23]["fingerprint_256"],"different normalized operations have distinct descriptors");auto serialized=page["items"];tool(e,"build_function_similarity_index",{{"workers",4}});check(tool(e,"get_function_similarity_index",{{"limit",5000}})["items"]==serialized,"parallel prefix construction deterministic");auto query=tool(e,"find_similar_functions",{{"addresses",Json::array({"0x1000"})},{"top_k",16},{"mode","cpu"}});check(query["backend_requested"]=="cpu"&&query["backend_used"]=="cpu","explicitCPU search usesCPU with no GPU requirement");check(query["queries"][0]["matches"].size()==16,"self exclusion still yields full requestedtop16");check(query["queries"][0]["matches"][0]["address"]=="0x1020"&&query["queries"][0]["matches"][15]["address"]=="0x1200","equal-distance ties sorted by indexedaddress after self exclusion");check(query["queries"][0]["matches"][0]["distance"]==0&&query["semantic_equivalence_proven"]==false,"identical descriptors are not semantic proof");auto repeated=tool(e,"find_similar_functions",{{"addresses",Json::array({"0x1000"})},{"top_k",16},{"mode","cpu"}});check(query["queries"]==repeated["queries"],"repeatedCPUtopk deterministic");auto inclusive=tool(e,"find_similar_functions",{{"addresses",Json::array({"0x1000"})},{"top_k",1},{"mode","cpu"},{"exclude_self",false}});check(inclusive["queries"][0]["matches"][0]["address"]=="0x1000","explicit self inclusion supported");e.editableBinary()->functions[1].name="renamed_live";page=tool(e,"get_function_similarity_index",{{"offset",1},{"limit",1}});check(page["cache_stale"]==false&&page["items"][0]["name"]=="renamed_live","renames update labels without stale descriptor cache");query=tool(e,"find_similar_functions",{{"addresses",Json::array({"0x1000"})},{"top_k",1},{"mode","cpu"}});check(query["queries"][0]["matches"][0]["name"]=="renamed_live","search resolves latest names");check(tool(e,"get_acceleration_info")["latest_result"]["operation"]=="find_similar_functions","latest compact status stored");e.editableBinary()->functions[0].end=0x1002;check(tool(e,"get_function_similarity_index")["cache_stale"]==true,"exclusive end edits invalidate index");check(throws(e,"find_similar_functions",{{"addresses",Json::array({"0x1000"})},{"mode","cpu"}}),"stale index cannot search");auto bounded=tool(e,"build_function_similarity_index");check(bounded["index_size"]==23&&bounded["skipped_short"]==1,"proven exclusive end prevents prefix crossing");e.editableBinary()->functions[0].end=0;tool(e,"build_function_similarity_index");e.advancedState()["manual"]["ranges"]=Json::array({{{"start","0x1001"},{"end","0x100a"},{"kind","data"}}});check(tool(e,"get_acceleration_info")["index"]["stale"]==true,"manual data edits invalidate fingerprints");check(tool(e,"build_function_similarity_index")["index_size"]==23,"manual data bytes cannot enter fingerprint");e.advancedState()["manual"]["deleted_functions"]=Json::array({"0x1020"});check(tool(e,"build_function_similarity_index")["index_size"]==22,"manual deleted starts cannot contribute fingerprints");e.advancedState()["manual"]=Json::object();auto limited=tool(e,"build_function_similarity_index",{{"max_functions",2}});check(limited["index_size"]==2&&limited["function_budget_exhausted"]==true&&limited["truncated"]==true,"function count cap exact and disclosed");std::atomic_bool flag=true;e.setCancellation(&flag);check(throws(e,"build_function_similarity_index"),"preexisting cancellation prevents index work");check(throws(e,"find_similar_functions",{{"addresses",Json::array({"0x1000"})},{"mode","cpu"}}),"preexisting cancellation prevents cached searches");e.setCancellation(nullptr);check(tool(e,"get_function_similarity_index")["total"]==2,"cancelled rebuild preserves prior index");check(throws(e,"find_similar_functions",{{"addresses",Json::array({"0x1001"})},{"mode","cpu"}}),"unknown interior query address rejected");check(throws(e,"find_similar_functions",{{"addresses",Json::array()},{"mode","cpu"}}),"empty query rejected");check(throws(e,"find_similar_functions",{{"addresses",Json::array({"0x1000"})},{"top_k",17},{"mode","cpu"}}),"publictopk capped16");check(throws(e,"build_function_similarity_index",{{"workers",17}}),"worker count bounded");check(throws(e,"build_function_similarity_index",{{"per_function_instruction_budget",257}}),"prefix work bounded");check(accelerationTools().size()==4,"four feature tools registered");check(!callAccelerationTool(e,"other",Json::object()),"unknown tool falls through");check(callAdvancedTool(e,"get_acceleration_info",Json::object()).has_value(),"advanced registry routes accelerator tools");std::cout<<"PASS: "<<checks<<" function similarity feature checks\n";return 0;
}catch(const std::exception& ex){std::cerr<<"FAIL after "<<checks<<" checks: "<<ex.what()<<'\n';return 1;}}
